CREATE TABLE IF NOT EXISTS teams (id text PRIMARY KEY,name text NOT NULL,provider_ids jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS players (id text PRIMARY KEY,team_id text REFERENCES teams(id),name text NOT NULL,position text,provider_ids jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS games (id text PRIMARY KEY,season int,week int,home_team text REFERENCES teams(id),away_team text REFERENCES teams(id),kickoff timestamptz NOT NULL,venue jsonb);
CREATE TABLE IF NOT EXISTS model_versions (id text PRIMARY KEY,created_at timestamptz NOT NULL,configuration jsonb NOT NULL,validation jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS statistics (player_id text REFERENCES players(id),game_id text REFERENCES games(id),source text NOT NULL,observed_at timestamptz NOT NULL,values jsonb NOT NULL,PRIMARY KEY(player_id,game_id,source,observed_at));
CREATE TABLE IF NOT EXISTS injuries (player_id text REFERENCES players(id),observed_at timestamptz NOT NULL,source text NOT NULL,status text,details jsonb,PRIMARY KEY(player_id,observed_at,source));
CREATE TABLE IF NOT EXISTS weather (game_id text REFERENCES games(id),observed_at timestamptz NOT NULL,source text NOT NULL,forecast_at timestamptz,values jsonb NOT NULL,PRIMARY KEY(game_id,observed_at,source));
CREATE TABLE IF NOT EXISTS odds_snapshots (id bigserial PRIMARY KEY,game_id text REFERENCES games(id),player_id text REFERENCES players(id),provider_event_id text NOT NULL,player_name text NOT NULL,book text NOT NULL,market text NOT NULL,side text NOT NULL,line numeric,american_price int NOT NULL,observed_at timestamptz NOT NULL,provider_updated_at timestamptz,raw jsonb NOT NULL,UNIQUE(provider_event_id,player_name,book,market,side,line,observed_at));
CREATE INDEX IF NOT EXISTS odds_movement ON odds_snapshots(provider_event_id,player_name,market,book,observed_at);
CREATE TABLE IF NOT EXISTS features (player_id text REFERENCES players(id),game_id text REFERENCES games(id),as_of timestamptz NOT NULL,values jsonb NOT NULL,PRIMARY KEY(player_id,game_id,as_of));
CREATE TABLE IF NOT EXISTS predictions (id bigserial PRIMARY KEY,model_version text REFERENCES model_versions(id),player_id text REFERENCES players(id),game_id text REFERENCES games(id),market text NOT NULL,issued_at timestamptz NOT NULL,mean numeric NOT NULL,quantiles jsonb NOT NULL,validation_passed boolean NOT NULL,UNIQUE(model_version,player_id,game_id,market));
CREATE TABLE IF NOT EXISTS simulations (id bigserial PRIMARY KEY,prediction_id bigint REFERENCES predictions(id),created_at timestamptz NOT NULL,draws int NOT NULL,parameters jsonb NOT NULL,results jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS backtesting (prediction_id bigint REFERENCES predictions(id),actual numeric,settlement text,closing_price int,return_per_unit numeric,scored_at timestamptz,PRIMARY KEY(prediction_id));
CREATE TABLE IF NOT EXISTS ingestion_runs (id bigserial PRIMARY KEY,started_at timestamptz NOT NULL,completed_at timestamptz,provider text NOT NULL,status text NOT NULL,details jsonb);
